INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dino Crisis 2', 'Dino Crisis 2 is a third-person action-adventure game and sequel to Dino Crisis. In a change from the survival horror theme of the first game, Dino Crisis 2 is more shoot ''em up oriented. The character always runs, thus removing the need for the run button from the first game, a second gun can be carried and more weapons were added to the game. Besides changes to the gameplay, the game also introduces new species of dinosaurs and lizards.' FROM games WHERE igdb_id = 4132 ON CONFLICT (game_id, language_code) DO NOTHING;
