INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Warrior VII', 'Dragon Quest VII is the seventh installment of the popular Dragon Quest series of role playing games and the first in the series to not be a part of a larger trilogy. It was the first main series Dragon Quest title to be released outside of Japan since the release of Dragon Quest IV: Chapters of the Chosen in North America in 1992, and the last DQ title to be released in North America with the Dragon Warrior name.' FROM games WHERE igdb_id = 1818 ON CONFLICT (game_id, language_code) DO NOTHING;
