INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-grinch', 15487, '2000-10-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7t1v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/pj29sx1bcxkuq0esqzf9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Grinch', 'First, it was a beloved book, then it was an animated special, next it was a movie, and now Dr. Seuss'' HOW THE GRINCH STOLE CHRISTMAS is a hand-held video game. You play both the Grinch and his faithful pooch, Max, in this creative adaptation. Much like the classic story, THE GRINCH takes place in the idyllic Whoville--where your aim is to cease the event called Christmas. You attempt to do so by wreaking havoc and solving challenging puzzles. The folks of Whoville will try to stop your efforts with love and happiness (blech!), so be on your toes if you hope to avoid them and effectively ruin the holiday. To make things a little easier, you can throw snowballs at the peacenik villagers to keep them at a distance. Each level will present new obstacles and challenges, and the Dr. Seuss world is faithfully translated to the video game format. Whether you''re a genuine grouch or you''re just in the mood for a great adventure, THE GRINCH is hilarious fun for everyone.' FROM games WHERE igdb_id = 15487 ON CONFLICT (game_id, language_code) DO NOTHING;
