INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pac-man-adventures-in-time', 78239, '2000-10-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2qx5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7f3b.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pac-Man: Adventures in Time', 'As in the original Pac-Man arcade game, the basic objective of each level is to guide Pac-Man through a maze while eating dots, unique food items, and power pellets that make Pac-Man''s enemies, the Ghosts, edible for a limited time. The ability to jump returns from Pac-Mania for bypassing hazards and avoiding enemies. Some levels contain obstacles such as deadly boulders, animals who delay or kill Pac-Man, and explosive projectiles. After every few rounds there is a bonus mini-game in which the player can obtain some extra points (with every 50,000 points earning Pac-Man an extra life). The levels also feature a variety of shapes and architectural features such as cylindrical mazes, canopies, bridges, pyramids, and even walls that allow Pac-Man to walk vertically. The game features more sophisticated events than its arcade predecessor, such as collecting a certain number of pellets to unlock another area of a maze. The game also includes the ability to see the short intermission videos that come before a new level and allow for an option of non-storyline play on specific levels. The game also has the ability to connect over the Internet for multiplayer mini-games.' FROM games WHERE igdb_id = 78239 ON CONFLICT (game_id, language_code) DO NOTHING;
