INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Racer Arcade', 'Star Wars Racer Arcade is a podracing arcade game produced by Sega and released in 2000. There are four tracks in the game, each with their own level of difficulty: Bantha Tracks (Easy), Smuggler''s Cove (Normal), Pixelito Challenge (Hard) and Boonta Eve Classic (Expert). The player can assume the role of either Anakin Skywalker, Ben Quadinaros, Gasgano or Sebulba.' FROM games WHERE igdb_id = 67944 ON CONFLICT (game_id, language_code) DO NOTHING;
