INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ultimate-fighting-championship', 24176, '2000-08-30', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3g8w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm76g.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Fighting Championship', 'The Ultimate Fighting Championship tournaments started in the 1990s, giving martial artists of the world a chance to distinguish themselves in a fighting environment with very few rules. Fighters could be matched up against fighters of any style, and the match ended only when one fighter submitted. The popularity of the sport resulted in the creation of other mixed martial arts tournaments and the evolution and merging of fighting styles for greater effectiveness. Ultimate Fighting Championship is a 3D fighting game that tries to simulate the experience of a real mixed martial arts fight. Players can choose from a selection of established UFC fighters, or create their own fighter through the Career Mode. While in Career Mode, players start the character creation process by selecting from several style templates, then using points earned through fighting and beating a series of progressively more difficult fighters to buy attribute upgrades in stamina, endurance, punching ability, kicking ability, or to learn certain techniques.' FROM games WHERE igdb_id = 24176 ON CONFLICT (game_id, language_code) DO NOTHING;
