INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('unreal-tournament-game-of-the-year-edition', 24723, '2000-10-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co635k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/argfm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unreal Tournament: Game of the Year Edition', 'Unreal Tournament is a first-person shooter video game developed by Epic Games and Digital Extremes. The second installment in the Unreal series, it was first published by GT Interactive in 1999 for Microsoft Windows, and later released on the PlayStation 2 by Infogrames, and on the Dreamcast by Secret Level. Players compete in a series of matches of various types, with the general aim of out-killing opponents. The PC version supports multiplayer online or over a local area network. Free expansion packs were released, some of which were bundled with a 2000 re-release: Unreal Tournament: Game of the Year Edition. The game is based on the same technology that powered Unreal, but the design of Unreal Tournament shifted the series'' focus to competitive multiplayer action. Development took 18 months, and the game was initially intended to be an expansion for Unreal. Unreal Tournament received critical acclaim, with reviewers praising the graphics, artificial intelligence and gameplay, although the console ports were noted for having limitations. The game won several awards, and remakes have been attempted by fans. The series has continued with the releases of sequels Unreal Tournament 2003 in 2002, Unreal Tournament 2004 in 2004, and Unreal Tournament 3 in 2007.' FROM games WHERE igdb_id = 24723 ON CONFLICT (game_id, language_code) DO NOTHING;
