INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('walt-disney-world-quest-magical-racing-tour', 8129, '2000-03-23', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ru5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7dcs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Walt Disney World Quest: Magical Racing Tour', 'Walt Disney World Quest Magical Racing Tour boasts more playable characters than any kart racer before it (a total of 13 are offered), and each of the game''s tracks allows you to maneuver a different vehicle. Instead of being confined to just a go-kart, you''ll get a bobsled, or a rocket ship, and several others. Collect a myriad of power-ups to your vehicle such as Mickey coins which allow you to race a little faster with each additional coin you collect. Or use the guided bottle rocket to get a speed boost and home in on your opponent. You can also collect items that can be used against your opponents like the frog spell, which will leave them hopping in your dust. Or launch an acorn at them and send them flying out of control.' FROM games WHERE igdb_id = 8129 ON CONFLICT (game_id, language_code) DO NOTHING;
