INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spawn: In the Demon''s Hand', 'The legendary hellbound comic anti-hero comes to life. Straight from the blockbuster arcade game, this home version kicks it up a notch with ever more features and modes of play. Up to 4 players can battle in the "death match-style" Battle Royal Mode or choose a computer controlled teammate to take on Team Battle Mode. All your favorite characters from the Spawn series are faithfully recreated in the ultimate death match challenge.' FROM games WHERE igdb_id = 4358 ON CONFLICT (game_id, language_code) DO NOTHING;
