INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heavy Metal: F.A.K.K. 2', 'Heavy Metal: F.A.K.K. 2 is a third-person shooter video game made by Ritual Entertainment in 2000. A sequel to the Heavy Metal 2000 animated movie, the game stars Julie in her quest to save her home planet of Eden from GITH, an ancient entity seeking to conquer the universe. Using a variety of weapons, Julie must now fight off GITH''s forces while at the same time uncovering a secret hidden deep within the planet.' FROM games WHERE igdb_id = 8290 ON CONFLICT (game_id, language_code) DO NOTHING;
