INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider-Man', 'YOU DON''T JUST PLAY IT... YOU LIVE IT He spins a web, swings across the sky and lands with a somersault onto the Daily Bugle building. Who is this masked hero? It''s you! Fight, jump and web-sling as Spider-Man as you take on a legion of sinister villains. The city is depending on you. Start swinging...' FROM games WHERE igdb_id = 3603 ON CONFLICT (game_id, language_code) DO NOTHING;
