INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('you-dont-know-jack-5th-dementia', 73383, '2000-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co50ct.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You Don''t Know Jack: 5th Dementia', 'Jack is back. And this time he has the internet with him. For the first time in the long running series, you can play with your mates over the internet. There are 600 questions that must be answered and a new game type called Bug out, where little bugs fly onto the screen and mention a few words. If the words don''t go with the clue, you must be the first to buzz in to splat the little guys. Other than that, this is the same Jack that we have (or haven''t) known for some time.' FROM games WHERE igdb_id = 73383 ON CONFLICT (game_id, language_code) DO NOTHING;
