INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek - Armada', 'Star Trek: Armada is a real-time strategy game published in 2000 by Activision. The game''s look and feel is based primarily on Star Trek: The Next Generation, and features a few of its main characters and ships. Playable factions include the United Federation of Planets, the Klingon Empire, the Romulan Star Empire and the Borg. The game received positive reviews and was noted for being one of the better Star Trek games to be made.' FROM games WHERE igdb_id = 18902 ON CONFLICT (game_id, language_code) DO NOTHING;
