INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Party 3', 'Mario Party 3 is the third and final Mario Party title for the Nintendo 64. A total of eight characters are available to choose from: Mario, Luigi, Princess Peach, Yoshi, Wario, Donkey Kong, and newcomers Waluigi and Princess Daisy. Mario Party 3 features duel maps, in which two players try to lower each other''s stamina to zero using non-playable characters such as Chain Chomps. It is the first Mario Party game to feature Luigi''s main voice and also it is last Mario game where Princess Daisy appears in a yellow and white dress, and with long hair, as well as the last Mario game (until New Super Mario Bros. Wii) in which Yoshi''s "record-scratching" voice is used. It is also the first Mario Party game to have multiple save slots.' FROM games WHERE igdb_id = 2329 ON CONFLICT (game_id, language_code) DO NOTHING;
