INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('alien-resurrection', 44995, '2000-10-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaszn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3zom.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Resurrection', 'Gameplay is standard FPS action, with limited ammo and plenty of hazards to detour around or find the switch to deactivate. The player switches between the four main characters at each level change, each with a slightly different set of abilities (Call has a motion tracker, Christie has his twin pistols from the film). Levels are based around keeping the Auriga running, and making their way through the ship to escape. This was to be Fox Interactive''s last Sega Saturn game, but development was pulled on the Saturn version before it was completed. PC and Dreamcast ports of the game were also planned but were never developed due to the original title''s poor sales.' FROM games WHERE igdb_id = 44995 ON CONFLICT (game_id, language_code) DO NOTHING;
