INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Sims', 'The Sims is a life-building simulation with emphasis on intimate details of individual characters rather than expansion of an entire society or civilization. You are in control of nearly every aspect of the lives of the individuals who make up your chosen population in the neighborhood. Characters are developed from the ground up and you infuse and mold them with personalities, looks, desires, moods, urges, living arrangements, career and personal choices, life styles, and reactions.' FROM games WHERE igdb_id = 223 ON CONFLICT (game_id, language_code) DO NOTHING;
