INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ridge Racer V', 'Ridge Racer V is all about excited drivers pursuing the sheer frantic fun of unrestricted racing. Players will be able to drive super-cars with supreme power, speed and style that just can''t be bought in a showroom. Features include four different modes – Grand Prix Mode, Versus Battle, Time Attack, and Free Run. Enhanced graphics, sound, and gameplay elements round out a package that also supports several steering wheel peripherals.' FROM games WHERE igdb_id = 10386 ON CONFLICT (game_id, language_code) DO NOTHING;
