INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digimon World 2', 'Digimon World 2 is a dungeon crawler video game developed by BEC and published by Bandai for the PlayStation as part of their Digimon series. It is the sequel to the original Digimon World, and was released in Japan in July 2000 and North America the following year in May 2001. The player controls Akira, a Digimon Tamer whose goal is to climb to the top of the Digimon World.' FROM games WHERE igdb_id = 36508 ON CONFLICT (game_id, language_code) DO NOTHING;
