INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daytona USA', 'Daytona USA is a remake of the arcade classic Daytona USA with upgraded graphics and expanded features. The game contains the original three arcade tracks, the two extra tracks from the Championship Circuit Edition, and three new tracks exclusive to this version, all of which can be reversed and/or mirrored for additional layouts. In addition to the usual time attack and single-track races, there is also a Championship mode that strings together multiple courses, as well as online play that was briefly available after the game''s launch.' FROM games WHERE igdb_id = 22007 ON CONFLICT (game_id, language_code) DO NOTHING;
