INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('1nsane', 9894, '2000-11-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wop.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mqhshls6wzsvvs6upgbo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1nsane', 'Levels are set in real world locations, scattered throughout North America, Europe, Africa, Asia and Australia. The actual design, however, is fictitious. The single player campaign comprises a series of championships in different vehicle classes, where the player unlocks new vehicles and locations, based on their score. Vehicles range from utility vehicles to light buggies and are either fictional or inspired by actual production vehicles. Though the names do not correspond with any actual vehicle, the fact is evident both visually in-game and in the names of the game''s files.' FROM games WHERE igdb_id = 9894 ON CONFLICT (game_id, language_code) DO NOTHING;
