INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ECW Hardcore Revolution', 'Often imitated, never duplicated, ECW Hardcore Revolution takes you to Hell and back with the most intense hardcore wrestling action the human body can endure. Remember, scars never heal. Debut of over 40 hardcore ECW stars including Rob Van Dam, Sabu, Tommy Dreamer, Raven, Mike Awesome, Francine and New Jack! Real gutter-mouth crowd chants and commentary from ECW''s Joey Styles. Brutal finishers and chair shots. "3-Way Dance" plus over 20 game modes!' FROM games WHERE igdb_id = 3483 ON CONFLICT (game_id, language_code) DO NOTHING;
