INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Capcom vs. SNK: Millennium Fight 2000', 'Two of the worlds greatest arcade fighter developers, Capcom and SNK, join forces to finally answer the question asked by many for years: Who is the dominant fighter? A range of fighters from both worlds are available to choose from, with two different fighting styles (Capcom and SNK, of course) meaning that players of both worlds can fit into the game easily, while new gamers can try Ryu using the SNK format.' FROM games WHERE igdb_id = 39593 ON CONFLICT (game_id, language_code) DO NOTHING;
