INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ring of Red', 'A highly classified prototype mech was stolen from the allied forces in southern Japan and it''s up to you to get it back! Take control of monstrous mechs and brave soldiers. Immerse yourself in detailed 3D battle sequences with an exciting style of gameplay that mixes in-depth strategy and real-time action as you lead the allies to victor' FROM games WHERE igdb_id = 22010 ON CONFLICT (game_id, language_code) DO NOTHING;
