INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tachyon: The Fringe', 'Caught in the middle of a violent conflict on the fringe of the galaxy - your ability to survive will depend on your piloting skills and combat savvy as a mercenary space fighter. But, as you explore the vastly detailed world of Tachyon: The Fringe, you will often find that the most powerful weapon on your ship is in your head.' FROM games WHERE igdb_id = 357 ON CONFLICT (game_id, language_code) DO NOTHING;
