INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil Survivor', 'Resident Evil Survivor is the first Resident Evil title to be rendered in real time as opposed to making use of pre-rendered backdrops. Levels are explored in first person, and when enemies are encountered the press of a button will bring up a targeting reticle for shooting. As with most light-gun games there is infinite pistol ammunition available, but limited ammunition for more powerful weapons. At the end of each level two doors are presented which both lead to different levels, although all paths eventually lead to the same ending.' FROM games WHERE igdb_id = 967 ON CONFLICT (game_id, language_code) DO NOTHING;
