INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Reign 2', 'The Imperium and Freedom Guard war lies in the distant future. Now is the era of another brutal clash between two sword enemies: the wealthy Jovian Detention Authority and the Sprawlers, a ragtag group of revolutionaries. Experience battle from both sides of the bloody front lines. For only then will you know what is it to Reign.' FROM games WHERE igdb_id = 11390 ON CONFLICT (game_id, language_code) DO NOTHING;
