INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('army-men-air-attack-2', 43949, '2000-10-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4epg.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Army Men: Air Attack 2', 'Army Men: Air Attack 2, the sequel to the PlayStation''s Army Men: Air Attack, has Captain Blade and his Alpha Wolf Squadron returning to action to continue the now infamous battles between the Green and Tan armies. The sequel features over twenty-five new missions with highly improved graphics, fully interactive environments, and gameplay reminiscent of Electronic Arts'' Strike series. Air Attack 2 has the same gameplay found in the first Air Attack game. You can move in all directions in this plastic 3D world using the left analog stick, strafe using the L1 and R1 buttons, and deploy various artillery, as well as use your chopper''s winch, using the controller''s face buttons. The different military hardware at your disposal depends on the helicopter and copilot you select between missions. These choices also have an impact on other aspects of the gameplay, such as weapons accuracy, winch speed, chopper speed, and the amount of abuse your craft can handle. These features offer nothing new in the way of gameplay, but their tight and responsive control more than make up for that.' FROM games WHERE igdb_id = 43949 ON CONFLICT (game_id, language_code) DO NOTHING;
