INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWF SmackDown! 2: Know Your Role', 'Prepare for the most outrageous WF experience ever created. Brawl in the ring, backstage, in the VIP room, the parking lot of the new WF New York. Let your fury rage in the new Tornado Tag Team mode. If that''s not hardcore enough, pull out the tables, ladders or chairs and really get nasty.' FROM games WHERE igdb_id = 6444 ON CONFLICT (game_id, language_code) DO NOTHING;
