INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Palette', 'Palette is a Japanese language freeware adventure game that was made with RPG Maker 95 by Nishida Yoshitaka. The game was highly acclaimed in the Fourth ASCII Entertainment Software Contest, awarded a Grand Prix of 10,000,000 yen, which resulted in remaking the game for PlayStation by Enterbrain. That version, entitled Forget me not -Palette-, saw the release on April 26, 2001 exclusively in Japan.' FROM games WHERE igdb_id = 62668 ON CONFLICT (game_id, language_code) DO NOTHING;
