INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crazy-climber-2000', 77399, '2000-02-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co98ko.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scuz0i.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Climber 2000', 'In 1980, Nichibutsu released Crazy Climber, in which players control a man attempting to scale a series of buildings using only his hands and feet, while avoiding a series of falling objects, mostly thrown by the building''s tenants. Crazy Climber 2000 takes the game play of the original and gives it a sweeping graphical makeover. The object is again to scale buildings while avoiding the falling objects thrown at you by its tenants, as well as windows that close on your fingers. The buildings themselves are laid out differently In the first stages, for example, the buildings start out as square skyscrapers. Later levels, however, require you to scale round ones. As well as this, new threats are introduced, such as: - Circling vultures that throw eggs at you. - Gorillas reaching out to grab you on both sides of the building. - Window cleaners that go from left to right, making you fall if you get in their way - Boulders thrown from elevators CC2000 also allows you to move from one face of the building to another. Also included is the original game, in all its early 80s glory.' FROM games WHERE igdb_id = 77399 ON CONFLICT (game_id, language_code) DO NOTHING;
