INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlezone 2: Combat Commander', 'Battlezone II: Combat Commander, often abbreviated to BZII, BZ2 or Bzone, is a 1999 computer game released by Pandemic Studios as a sequel to Activision''s 1998 Battlezone. Like Activision''s Battlezone, Battlezone II is a hybrid tank shooter, first-person shooter (FPS) and real-time strategy (RTS) game. The player pilots various futuristic vehicles, while using the function keys to select and command units and structures. Battlezone II features two races, the ISDF (humans) and the Scions (modified/upgraded humans).' FROM games WHERE igdb_id = 24122 ON CONFLICT (game_id, language_code) DO NOTHING;
