INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dance-dance-revolution-disney-mix', 44796, '2000-11-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49gg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scerwe.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution Disney Mix', 'The revolution continues with Dance Dance Revolution Disney Mix. Featuring your favorite Disney characters and dance mixes of popular Disney tunes, this is the hottest dancing game this side of Magic Kingdom. Get ready to heat up the dance floor and put your skills to the test as you move to the groove. Let Mickey and his friends make your dreams come true as you become a star. - Dance to high-energy remixes of popular Disney tunes, including It''s A Small World, Zip-A-Dee-Doo-Dah, and Mickey Mouse March. - Select from your favorite Disney characters, including Mickey Mouse, Donald Duck, Goofy and more! - Re-create the DDR experience with Konami''s Dance Dance Revolution controller (sold seperately). - Special Work Out features let you have fun getting in shape - while tracking the calories you burn. - Multiple difficulty settings makes DDR Disney Mix easy to learn for all ages.' FROM games WHERE igdb_id = 44796 ON CONFLICT (game_id, language_code) DO NOTHING;
