INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Icewind Dale', 'In the northernmost reaches of the Forgotten Realms lies a frozen and untamed region known as Icewind Dale. Journey deep into the Spines of the World mountains, a harsh and unforgiving territory teeming with fearsome and merciless beasts. There you must confront an ancient evil that threatens to unleash an unspeakable horror upon the face of Faerûn.' FROM games WHERE igdb_id = 753 ON CONFLICT (game_id, language_code) DO NOTHING;
