INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Puzzle League', 'Discover the most frantic, frenzied, fun-filled Pokémon challenge ever--Pokémon Puzzle League! Line up three or more blocks of the same type to clear them off the screen. Create chains and combos to send garbage to your opponent. Collect badges from other Pokémon trainers to earn the right to enter the ultimate competition... a battle against the mysterious Puzzle Master!' FROM games WHERE igdb_id = 3574 ON CONFLICT (game_id, language_code) DO NOTHING;
