INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fear Effect', 'Fear Effect is an action adventure waiting to unfold! Wee Ming Lam disappears a few days before her 18th birthday under mysterious circumstances. Three ruthless mercenaries conspire to track her down and ransom her off to her father, Mr. Lam, a powerful Triad leader in Hong Kong. An extortion mission to retrieve Wee Ming Lam becomes a lesson in survival against the most unimaginable of enemies.' FROM games WHERE igdb_id = 8600 ON CONFLICT (game_id, language_code) DO NOTHING;
