INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batman Beyond: Return of the Joker', 'Batman Beyond: Return of the Joker (also known as Batman of the Future: Return of the Joker in Europe and Australia) is a 2000 American direct-to-video animated film featuring the comic book superhero Batman and his archenemy, the Joker. It is set in the continuity of the animated series Batman Beyond, in which Bruce Wayne has retired from crime fighting, giving the mantle of Batman to high school student Terry McGinnis, and serves as a sequel to both Batman: The Animated Series and The New Batman Adventures. As in the TV series, Will Friedle and Kevin Conroy star as Terry McGinnis and Bruce Wayne, respectively. Mark Hamill, who played the Joker opposite Conroy in Batman: The Animated Series and The New Batman Adventures, reprises his role.' FROM games WHERE igdb_id = 3444 ON CONFLICT (game_id, language_code) DO NOTHING;
