INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Driver 2: Back on the Streets', 'Driver 2: Back on the Streets is an open-world driving and action game developed by Reflections Interactive and published by Infogrames in 2000 for the PlayStation. It is the sequel to Driver and follows undercover cop Tanner and his partner Jones as they investigate a crime syndicate. The game introduces the ability for players to exit vehicles and explore environments on foot. Missions take place across four cities: Chicago, Havana, Las Vegas, and Rio de Janeiro. Gameplay combines story-driven objectives with free-roaming exploration.' FROM games WHERE igdb_id = 6391 ON CONFLICT (game_id, language_code) DO NOTHING;
