INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tony-hawk-s-pro-skater-2', 913, '2000-09-19', 87, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1y77.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hvmunwh0xeynzbvplzaw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tony Hawk''s Pro Skater 2', 'Tony Hawk''s Pro Skater 2 redefined an already great game. Its addition of stellar new features (like Create-A-Park), and great game-play tweaks (the manual maneuver will be copied for years to come) made it the best installment in a killer series of games. Anyone who has ever skated the Philadelphia level will agree -- this game is a masterpiece of level design. Hell, it''s a masterpiece all around. There isn''t a bad park or dull moment, just pure gaming nirvana!' FROM games WHERE igdb_id = 913 ON CONFLICT (game_id, language_code) DO NOTHING;
