INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy IX', 'Final Fantasy IX is the ninth main installment in the FF series. The title is a return to the series''s roots, with gameplay features and references to the past games featuring throughout, as well as a medieval fantasy setting and cartoonish art style as a break from the sci-fi slant style of Final Fantasy VII and Final Fantasy VIII.' FROM games WHERE igdb_id = 421 ON CONFLICT (game_id, language_code) DO NOTHING;
