INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Covert Ops: Nuclear Dawn', 'Covert Ops: Nuclear Dawn, otherwise known as Chase the Express, is a video game created by Sugar and Rockets for the PlayStation, and released in 2000. On March 16, 2000 Activision announced that they had acquired the North American publishing rights to Sony Computer Entertainment''s Japanese action-adventure game, Chase The Express. The game was then renamed Covert Ops: Nuclear Dawn for the North American market.' FROM games WHERE igdb_id = 4137 ON CONFLICT (game_id, language_code) DO NOTHING;
