INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Walt Disney''s The Jungle Book Rhythm N'' Groove', 'Sampling a good beat from Dance Dance Revolution, Disney Interactive and Ubi Soft have a new groove going in Jungle Book: Rhythm n'' Groove. The game brings all of your favorite characters from Disney''s animated movie The Jungle Book and gives them something to dance to. You get to see Baloo, Mowgli, King Louie, and others get their Jungle Boogie going to remixed Jungle Book songs like "Bear Necessities". Two players can battle it out for King of the Jungle in two-player dance-offs. Yo Bagheera... Do the Funky Panther!' FROM games WHERE igdb_id = 43375 ON CONFLICT (game_id, language_code) DO NOTHING;
