INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ikachan', 'In Ikachan, you control a squid in an underwater cave system. This game uses what is assumed to be an early version of the Cave Story engine. The controls are built around the use of momentum. The caverns are cut off from the sea, there are food shortages, and a fish named ironhead rules the tunnels with an iron, uhh.. head. You must set things right.' FROM games WHERE igdb_id = 15466 ON CONFLICT (game_id, language_code) DO NOTHING;
