INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('frogger-2-swampys-revenge', 11466, '2000-08-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2q73.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm6vz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frogger 2: Swampy''s Revenge', 'Because of his envy of Frogger''s achievements and the attention he receives, Swampy the Crocodile hatches a devious scheme to invade his pond and kidnap Lillie Frog''s brothers and sisters. What a vile crocodile! Assuming the role of the vengeful frog, you must thwart the evil crocodile and save the innocent tadpoles from harm. Divided into various interactive 3D worlds, Frogger''s mission spans over 30 levels crammed with life threatening obstacles and monstrous cronies blocking the path to victory. Fortunately, the frog has been endowed with supreme powers including regular hops and super-hops, the ability to float over water and land, a Power Croak for calling missing tadpoles and a bug-seeking tongue.' FROM games WHERE igdb_id = 11466 ON CONFLICT (game_id, language_code) DO NOTHING;
