INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Demolition', 'Star Wars: Demolition is a vehicular combat game set in the Star Wars universe created by both Luxoflux and LucasArts using the Vigilante 8 game engine. The premise of the game is that the Galactic Empire declares they have officially banned Jabba the Hutt''s podraces, so Jabba creates a more life-threatening vehicular combat contest to replace the sport of podracing.' FROM games WHERE igdb_id = 143 ON CONFLICT (game_id, language_code) DO NOTHING;
