INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fifa-2001-major-league-soccer', 698, '2000-10-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1tan.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8z44.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FIFA 2001: Major League Soccer', 'FIFA 2001 aims to immerse its fans with the most realistic football experience possible. Over 50 international teams, including England, France, Germany, Holland, Spain, and the United States have made the cut, while 17 of the planet''s top leagues have been incorporated as well. New motion captured moves from Matthaus, Mendieta, Scholes, and other soccer legends support the game''s realism, with animated linesman and authentic light sourcing add that much more to the presentation. Perhaps the most important features, though, are the advanced sets of artificial intelligence, in-game cinematic cutscenes, and a ton of game modes that have been specially built for tournaments from around the world.' FROM games WHERE igdb_id = 698 ON CONFLICT (game_id, language_code) DO NOTHING;
