INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Looney Tunes: Space Race', 'Looney Tunes: Space Race features eight all-time favorite characters, including Bugs Bunny, Daffy Duck, Taz, Sylvester, Yosemite Sam, and Wile E. Coyote. The 12 tracks include shortcuts, jumps, and traps, and there are over 40 competitive events. Players can pummel opponents with gags like the portable hole, falling elephants, retractable boxing glove, and instant storm. Up to four players can race at a time.' FROM games WHERE igdb_id = 8136 ON CONFLICT (game_id, language_code) DO NOTHING;
