INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daikatana', 'Daikatana is a first-person shooter action role-playing game developed by Ion Storm. It was published by Eidos Interactive for Windows and Kemco for Nintendo 64. Players control a swordsmaster who travels through various time periods using the eponymous Daikatana, a powerful sword tied to the fate of the world.' FROM games WHERE igdb_id = 8201 ON CONFLICT (game_id, language_code) DO NOTHING;
