INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('giants-citizen-kabuto', 34, '2000-12-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xnq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4svt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Giants: Citizen Kabuto', 'Giants: Citizen Kabuto is a unique blend of action, strategy, and humor set in a fantastical world. Long before human civilization arose, a massive fragment of a lost planet, the Island, hurtled through space. This paradise was home to the towering giant Kabuto, created by the matriarchal Sea Reapers as a defense against intruders. But Kabuto became self-aware, and his loneliness and pain drove him to rampage. Meanwhile, space travelers known as the Meccs, searching for their missing friends, find themselves stranded on the Island. Forced to navigate the ongoing conflict between the Sea Reapers and the now-berserk Kabuto, the Meccs must use a mix of combat, stealth, and cunning to survive. With its engaging storyline, diverse characters, and blend of gameplay styles, Giants: Citizen Kabuto offers a one-of-a-kind experience where three factions vie for control of a truly unique and captivating world.' FROM games WHERE igdb_id = 34 ON CONFLICT (game_id, language_code) DO NOTHING;
