INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ms. Pac-Man: Maze Madness', 'Professor Pac learns that the witch, Mesmerelda, has seized control of the Enchanted Castle using black magic and from there is planning on stealing all four Gems of Virtue (Generosity; Truth; Wisdom; Courage) to control the "four wonders" (areas of Pac-Land). He creates a device called a Pactrometer which allows Ms. Pac-Man to go to these areas to recover the gems before Mesmerelda can get them first.' FROM games WHERE igdb_id = 3338 ON CONFLICT (game_id, language_code) DO NOTHING;
