INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crash Bash', 'Crash Bash is a party game in which four people can play several mini-games as characters from the Crash Bandicoot series. The gameplay consists of 28 different mini-games and three distinct modes of play: Adventure, Battle, and Tournament. Crash Bash includes multiplayer compatibility for up to four human players with the use of the PlayStation Multitap. The games are organized from a central hub world from which spokes lead to different levels.' FROM games WHERE igdb_id = 1195 ON CONFLICT (game_id, language_code) DO NOTHING;
