INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sydney 2000', 'Sydney 2000 is the official Video Game of the Olympic Games. It features 32 countries represented in 12 events: 100M Sprint, 110M Hurdles, Hammer, Javelin, Triple Jump, High Jump, 100M Freestyle Swimming, Olympic Sprint Cycling, Skeet Shooting, Super Heavyweight Weight Lifting, 10M Platform Diving and Kayak K1 Slalom.' FROM games WHERE igdb_id = 8333 ON CONFLICT (game_id, language_code) DO NOTHING;
