INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gold-and-glory-the-road-to-el-dorado', 13776, '2000-11-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25i5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/srzsfqiboyv1f0ocfcgv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gold and Glory: The Road to El Dorado', 'After stowing away on Cortes''s ship bound for the New World, Miguel and Tulio find themselves in a strange land with no food. However, they do find part of a map that might lead them to El Dorado, the lost city of gold. You take the role of either Miguel or Tulio as they search 20 levels of action that span swamps, rainforests, Spanish galleons, and even El Dorado for treasure and the other pieces of the map. Along the way, the heroes will have to fight bulls, native warriors, Spanish soldiers, wild boars, and rhinos, and they''ll also have to brave the Circle of Fire. Luckily, the heroes are equipped with swords to dispatch any problems they might run into. If you play the game well, you just might get to ride Altivo, the horse. Help Miguel and Tulio find GOLD AND GLORY: The Road to El Dorado.' FROM games WHERE igdb_id = 13776 ON CONFLICT (game_id, language_code) DO NOTHING;
