INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('soulbringer', 9281, '2000-06-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1q7v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21mr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soulbringer', 'Thousands of years ago six demon kings, known as the Revenants, ruled the world with an iron fist and bloody swords. Donning the bodies of mortal vassals, they could live in the realms of man forever. The great hero and warlock Harbinger was the only one who could stand up to their power. One by one he hunted the Revenants, taking their spirits and casting them into the Well of Souls. Alas, the Revenants survived. As a young man you will travel to meet your uncle in the town of Madrigal. There, your destiny draws you into the path that Harbinger trod - to confront the Revenants and banish their souls back to the Well forever. Your travels will take you far from Madrigal, to the ruined kingdoms of Horath, the ancient empire of Thardolin, and through the lost city of Talendrah. You will brave searing deserts and icy plains. You will have to seek answers among the living and the dead. Customizable combat and magic system that can be as simple or as complex as you like. Compelling story with many twists and turns will keep you hooked for hours. Dynamic music, high quality voice acting, and more than one possible ending.' FROM games WHERE igdb_id = 9281 ON CONFLICT (game_id, language_code) DO NOTHING;
