INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dracula: Resurrection', 'A fright-filled Adventure that transpires in the heart of Transylvania. London 1904. Seven years after the slaying of Dracula, you play as Jonathan Harker, (the protagonist from Bram Stoker''s original novel) and soon discover your wife, Mina has fled London for the Count''s castle in Transylvania. Has Mina fallen prey to vampires?' FROM games WHERE igdb_id = 9091 ON CONFLICT (game_id, language_code) DO NOTHING;
