INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Summoner', 'Born with the mark of the Summoner, Joseph possesses a power greater than emperors and gods. As a child, he summoned a demon to save his village, and watched in horror as those he loved were destroyed. Nine years later, the armies of Orenia invade, and Joseph must confront the prophecy he was born to fulfill.' FROM games WHERE igdb_id = 3103 ON CONFLICT (game_id, language_code) DO NOTHING;
