INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swing', 'Swing is a classic game for the Game Boy Color platform. It is a thrilling platformer that combines action and adventure elements. Players control a character equipped with a grappling hook, swinging through challenging levels filled with enemies and obstacles. The game offers a unique gameplay mechanic centered around swinging mechanics, providing an exhilarating experience. With its engaging gameplay and captivating levels, Swing provides hours of fun and excitement for players of all ages.' FROM games WHERE igdb_id = 85912 ON CONFLICT (game_id, language_code) DO NOTHING;
