INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('starlancer', 11230, '2000-03-31', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jps.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/syrbyn5rmkkpjzxiuise.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'StarLancer', 'Starlancer is a space-based science fiction flight simulator computer game, created by Erin Roberts, Chris Roberts, and Warthog PLC under the auspices of Digital Anvil. It is the year 2160. Mankind has colonized the solar system and two political entities have emerged: the Alliance consisting of American, Australian, French, Spanish, Italian, Japanese, British and German forces, and The Coalition of Russian, Chinese and Middle-Eastern interests. The game begins with a surprise attack on Fort Kennedy, where a peace treaty turns into a bloodbath: all of the inner four planets are overrun, including Terra herself, and the Italian and French fleets are utterly lost. The Alliance fleet regroups at Triton, Neptune''s moon, and attempts to regain lost territory. The player takes the role of a rookie pilot in the international 45th Volunteers squadron, under the command of Captain Robert Foster and Wing Commander Maria Enriquez, aboard the re-commissioned British carrier ANS Reliant. As with Wing Commander: Prophecy, the pilot''s flying ability is the only meter by which success and failure is measured, though Starlancer does not feature as many branching mission paths. As in Wing Commander I the pilot may be promoted throughout the course of the campaign; unlike WCI, their rank determines which fighters and missiles they may choose to employ during each mission. The game provides a "virtual carrier" through which to navigate, including nearby crewmembers whose reaction to you depends on your current rank and standing. However, the true gem of the game lies in its textual and video news broadcasts, which keep the player informed as to the status of the rest of the war, which seems to be progressing just over the horizon. Players frequently find themselves flying alongside squadrons and pilots they have heard about on the news just recently, providing a dose of ''celebrity exposure'' and also increasing the sensation that they are just one part of a much larger war effort. Starlancer''s story is continued in Chris Roberts'' Freelancer project, though the two belong to different subgenres (the first is purely focused on action, the latter also features trading and the player can freely move through the game''s universe when they are not on a mission.)' FROM games WHERE igdb_id = 11230 ON CONFLICT (game_id, language_code) DO NOTHING;
