INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You Don''t Know Jack: Louder! Faster! Funnier!', 'YOU DON''T KNOW JACK Louder! Faster! Funnier! showcases the wildest and wackiest episodes from YOU DON''T KNOW JACK the Net Show -1000 questions chock full of JACK attitude deliver a prime-time trivia showdown for you and your friends. Choose from over 45 hilarious episodes to test your wits and tickle your funnybone. Includes a brand-new question type and a favorites feature so you can save and enjoy your favorite episodes!' FROM games WHERE igdb_id = 73213 ON CONFLICT (game_id, language_code) DO NOTHING;
