INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Colony Wars: Red Sun', 'Red Sun is the third in Psygnosis'' Star Wars inspired "Colony Wars" saga. This time around you follow the personal quest of Valdmar a miner who gets caught up in the wars between the League and the Navy after meeting the enigmatic "General" in a series of mysterious dreams.' FROM games WHERE igdb_id = 8282 ON CONFLICT (game_id, language_code) DO NOTHING;
