INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NASCAR 2001', 'Authentic Nascar Racing: The real drivers, cars, teams, tracks, sponsers, and rules. Top Drivers: Over 30 drivers including Jeff Gordon, Dale Earnhardt, Tony Stewart, Dale Jarrett, Bobby Labonte, Mark Martin, Dale Earnhardt Jr and Bobby Hamilton. More Tracks: Daytona and 13 other Nascar tracks with both day and night racing. Full or "Track Pack" Season: Race a full or half Nascar season or choose to compete on track packs: race just on short tracks, road courses, speedways or superspeedways.' FROM games WHERE igdb_id = 45099 ON CONFLICT (game_id, language_code) DO NOTHING;
