INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('holiday-racer', 144386, '2000-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7yfp.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Holiday Racer', 'Holiday Racer is another entry in the Davilex Racer series where the player takes part in a TV show. The price is a free trailer pitch in Monaco. But of course the player has to work for it - in this case the task is to win six illegal street races in Aachen, Paris, Lyon, Marseilles, Monaco and Nice. There are five humorous exaggerated persons to choose, e.g. a hippie or a stressed family father. The races are heavily action oriented and include power-ups which either increase the top speed, freeze other cars or repair the own vehicle. Between the races the player can invest earned points in better tires, engines or gearboxes; he also can gamble for other equipment. The available vehicles are no regular cars but jet ski trailers or jeeps. When beating the game with all vehicle types the player unlocks a special car.' FROM games WHERE igdb_id = 144386 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 144386 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
