INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcatera: The Dark Brotherhood', 'Arcatera is a role-playing game. Much of the gameplay is dedicated to exploring the town and its surroundings, talking to people and gathering information that will advance the story. The player can choose to start the game as any of the four available characters: a fighter, a thief, a magician, and a monk. A port for the Sega Dreamcast was developed, but never released.' FROM games WHERE igdb_id = 24134 ON CONFLICT (game_id, language_code) DO NOTHING;
