INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mille Miglia', 'Mille Milgia, the racers ultimate fantasy, the very embodiment of Italian style and passion. Pioneers of car design from Enzo Ferrari to the Maserati brothers'' hand built car for racing legends such as Nuvolari, Fangio and Moss. Now it''s your turn to sit behind the wheel of these incredible classic cars and race over 10 tracks through italian towns, cities and stunning countryside.' FROM games WHERE igdb_id = 37260 ON CONFLICT (game_id, language_code) DO NOTHING;
