INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scooby-Doo! Classic Creep Capers', 'Like wow! Scooby and the gang face off against some all-time classic villains, including The Witch Doctor, The Black Knight, and The Snow Ghost. Help guide Scooby and the gang through three classic episodes and one all-new episode. It''s your job to search for clues and unmask the ghoulish villains!' FROM games WHERE igdb_id = 2858 ON CONFLICT (game_id, language_code) DO NOTHING;
