INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lightslayer', 127784, '2000-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vff.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7gp8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lightslayer', 'Lightslayer is an action role-playing game played in first person perspective. As a dark elven sorceress, you travel through a vast world, fighting monsters and completing quests in the search for your missing mentor.  Lightslayer was my first commercial game, originally released in the year 2000, almost 20 years ago. This is version 3, which I have upgraded for newer computers. Changes include:  OpenGL-accelerated rendering.  Run at the native full screen resolution, or in a resizeable window.  Full mouse support, in the menus and the actual game.  A few minor user interface and game balance improvements.  The original Wrath of Darkness game included as a bonus.  However, the actual content of the game is untouched, in all of its primitive programmer-art glory. Overall, I think this game has held up incredibly well to the test of time, which is another way of saying that the ugly and clunky aspects of the game were already ugly and clunky when the game was first released.' FROM games WHERE igdb_id = 127784 ON CONFLICT (game_id, language_code) DO NOTHING;
