INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The New Adventures of the Time Machine', 'Inspired by the classic story of H.G. Wells, take the role of an intrepid time adventurer trapped in a mysterious future. The only way home may be the demi-god Khronos, Master of the Hourglass... In a similar manner to Myst, players move around a 3-dimensional world in first person. Collect objects and explore various locations to solve various puzzles. Speak with other characters and grapple with action elements during the game''s 40+ hours of playing time.' FROM games WHERE igdb_id = 24127 ON CONFLICT (game_id, language_code) DO NOTHING;
