INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Orphen: Scion of Sorcery', 'SORCERER BY CALLING. HERO BY ACCIDENT. As Orphen, the powerful but lazy sorcerer, you''ve always thought being a hero was too much work. But now, you don''t have a choice. Harnessed into a risky adventure, you must use your dark powers to help your desperate companions resolve their unique quests.' FROM games WHERE igdb_id = 24165 ON CONFLICT (game_id, language_code) DO NOTHING;
