INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of the Prophet & the Assassin', 'In the mythical East of the 13th century, a knight turned bandit is searching for a false prophet to exact a terrible revenge.  The Legend of the Prophet & the Assassin is an adventure game released in 2000 Arxel Tribe and Wanadoo Edition. It is develop by Arxel Tribe. The game is inspired by the work of Brazilian novelist Paulo Coelho.' FROM games WHERE igdb_id = 125010 ON CONFLICT (game_id, language_code) DO NOTHING;
