INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Earth 2150', 'The 21st century was supposed to herald the dawn of a new age. The wars, famines and suffering of the last 20 millennia were to become a distant, fading memory, as scientific advances brought global peace and prosperity. The anticipated global conflict broke out with a violence that shook the planet to its core.' FROM games WHERE igdb_id = 8932 ON CONFLICT (game_id, language_code) DO NOTHING;
