INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F1 Championship Season 2000', 'F1 CHAMPIONSHIP Season 2000, featuring all the drama, action, and emotion of the 2000 season, takes the player right to the heart of the thrilling world of Formula One racing. Re-live the gladiatorial battles between Michael Schumacher and David Coulthard or tear up the record books and take an outsider to World Championship glory. In-depth behind the scenes technical support from the Orange Arrows and Benetton Formula One teams allows the game player to enter the world of Formula One racing in unprecedented detail and authenticity.' FROM games WHERE igdb_id = 690 ON CONFLICT (game_id, language_code) DO NOTHING;
