INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Die Hard Trilogy 2: Viva Las Vegas', 'Ready to kick some more terrorist butt? In Die Hard Trilogy 2: Viva Las Vegas for the PlayStation, you''ll reprise the role of John McClane as you lay waste to the threats and save innocent people along the way -- this time in the Sin City capital of the world: Las Vegas, Nevada. The game comes packaged as a three-in-one deal, just like the original Die Hard Trilogy, for a total of 25 non-stop action-packed levels.' FROM games WHERE igdb_id = 44952 ON CONFLICT (game_id, language_code) DO NOTHING;
