INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jagged Alliance 2: Unfinished Business', 'The smoke is clearing and the bullets have stopped flying. Arulco is free at last, but your job''s not over. An all-powerful corporation is assaulting the tiny country, and once again, you''re needed! Enter a whole new chapter of the critically acclaimed Jagged Alliance 2 with all new weapons, new mercenaries, new terrains and the fantastic new Mission Builder! Gear up - you''ve got some Unfinished Business to take care of!' FROM games WHERE igdb_id = 51205 ON CONFLICT (game_id, language_code) DO NOTHING;
