INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('snow-drop', 71444, '2000-07-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5y3a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckemi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snow Drop', 'Snow drop is a beautiful European herb known for bearing nodding white flowers that often appear while the snow is on the ground, despite the cold of winter around it. Filled with symbolism of "hope" and "consolation," the beautiful flower is the central theme in Snow Drop, the romantic wintertime bishoujo adventure from Peach Princess! You are Minoru Sasazuka, age 19, a bit of a dreamer with a difficult tendency of not being able to make decisions when your heart is involved. A normal Japanese boy, trying to get into college, you''ve got a handsome physique that should make you popular with girls, but your occasional penchant for romanticism drives them away. Invited on a winter dream ski trip with a group of friends, you head for a ski lodge for some winter skiing and fun. For you, it''s a journey home, since you frequented this particular lodge since when you were young. With you are Kyoka, a very special childhood friend of yours, her stylish sister Keika, and your sister, Honami. At the lodge, you enjoy the hospitality of the owner, Kasumi, a competent woman with a tinge of sadness in her eyes. Also at the lodge is the lovely Shizuka, the mysterious helper who has many secrets. As the story develops, you are confronted with the reality that Kyoka, your friend since childhood, loves you. You''ve suspected this, but haven''t ever been able to face this before now, with the magical and romantic winter snow all around you. At the same time, you are strangely attracted to the quiet and romantic Shizuka-chan -- which will you choose? Although many erotic temptations are in store in the quiet mountain retreat, and there are many paths you can choose, you must be true to your heart.' FROM games WHERE igdb_id = 71444 ON CONFLICT (game_id, language_code) DO NOTHING;
