INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1944: The Loop Master', 'The game takes place in the heated battles of 1944 during the Second World War as a super ace pilot attempts to defeat an entire army. The game operates and plays like most standard shooters. The objective of every level is to shoot enemy planes, tanks, trains, turrets, battleships, and defeat the boss after each level. Unlike its predecessor, 19XX: The War Against Destiny, the game plays more like the early games in the series.' FROM games WHERE igdb_id = 6079 ON CONFLICT (game_id, language_code) DO NOTHING;
