INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King of the Hill', 'Based on the FOX animation series of the same name, King of the Hill is about the Texan Hill family and their misadventures with their friends and neighbors. As a game, it''s actually two unrelated games (install and run separately). One is a romp through the neighborhood with little "parlor" type games such as Tic-Tac-Toss, Scavenger Hunt, and more. The other is a cartoony imitation of Deer Hunter.' FROM games WHERE igdb_id = 72285 ON CONFLICT (game_id, language_code) DO NOTHING;
