INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Smuggler''s Run', 'Drive, evade and explore anywhere across 3 vast levels - Rocky Mountain forest, desert and icy tundra. As a member of a gang of international smugglers, it''s your job to evade the U.S. Border Patrol, CIA and cutthroat rivals to deliver illegal cargo. It''ll take complete mastery of your off-road vehicle to make it across unforgiving terrain and stay one step ahead...and make the drop.' FROM games WHERE igdb_id = 4154 ON CONFLICT (game_id, language_code) DO NOTHING;
