INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spyro: Year of the Dragon', 'Spyro: Year of the Dragon is the third installment in the Spyro series and the last Spyro game Insomniac developed. In this 3D adventure, Spyro have to retrieve 150 eggs that the evil Sorceress has stolen from Dragonworld. To survive, he will have to utilize all of his signature moves along with several he''s recently picked up, like the ability to control vehicles like tanks, submarines, and speedboats. As an extra bonus, you have the option to choose from a wacky cast of characters: Sheila the kangaroo, Sergeant Byrd the flying penguin, Bentley the Yeti and Agent 9 the space monkey.' FROM games WHERE igdb_id = 1578 ON CONFLICT (game_id, language_code) DO NOTHING;
