INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('project-i-dot-g-i-dot-im-going-in', 3201, '2000-12-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mmm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lko9oqfzxyegf9t9bvne.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project I.G.I.: I''m Going In', 'Project I.G.I.: I''m Going In (released in Europe as simply Project I.G.I.) is a tactical first-person shooter developed by Innerloop Studios and released on December 15, 2000 by Eidos Interactive. It is one of the first computer games to feature realistic weaponry and tactical combat situations. Pursue and defeat a homicidal ex-Russian Colonel before she turns Europe into a nuclear wasteland in Project IGI: I''m Going In. This first-person shooter emphasizes stealth and guile instead of massive firepower. Jones has to sneak into the toughest military installations in Eastern Europe, and once inside, use his skills in thievery, computer hacking, sabotage, and reconnaissance to stop the madwoman. The enemy''s Artificial Intelligence will react to his every action and use military tactics to track his position. In order to counter its surveillance, bunkers, tanks, and gunships, Jones is equipped with NATO spy gear and assault weapons. If the odds get stacked too high against him, he can call in a napalm strike via his Map Computer. Upon release the game garnered mixed reviews due to a number of shortcomings, such as poorly programmed Artificial intelligence, lack of a mid-game save option, and the lack of multiplayer features. However it was praised for its superb sound design and graphics, thanks in part to its use of a proprietary game engine that was previously used in Innerloop''s Joint Strike Fighter. It was followed up in 2003 by I.G.I.-2: Covert Strike.' FROM games WHERE igdb_id = 3201 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 3201 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
