INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Bouncer', 'A typical evening at a local bar erupts into chaos as members of a Special Forces strike team descend through the roof to kidnap a young girl, Dominique. Three bouncers--Sion, Volt, and Kou--come to the rescue, only to see the invaders grab Dominique, retreat through a window, and escape. Now it''s up to you to save Dominique either alone or simultaneously with three friends. With The Bouncer''s 3D combat environment, battles can take place anywhere.' FROM games WHERE igdb_id = 1349 ON CONFLICT (game_id, language_code) DO NOTHING;
