INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tom-and-jerry-in-fists-of-furry', 2714, '2000-11-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4aoy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scgw9w.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom and Jerry in Fists of Furry', 'One-on-one fighting! Tag team tournaments! Just choose your character and then select the location. All the environments are modeled after scenes from your favorite Tom & Jerry episodes. An "All-Star" line-up of characters such as Tom, Jerry, Butch, Spike, Tuffy, and Duckling help to make this the ultimate Tom & Jerry experience! Weapons include shovels, bombs, red-hot pokers, tennis rackets, furniture and an assortment of fruit, plus there are countless other tricks, traps and surprises to be found. It doesn''t get any better than this. So go to your corner, wait for the bell and come out fighting. Just keep an eye out behind you, because no one fights fair in this game!' FROM games WHERE igdb_id = 2714 ON CONFLICT (game_id, language_code) DO NOTHING;
