INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thief II: The Metal Age', 'The ultimate thief is back! Tread softly as you make your way through 15 new complex, non-linear levels full of loot to steal and guards to outsmart. Improved enemy AI, new gadgets and a riveting story will draw you into the world of Thief II: The Metal Age, a place of powerful new technologies, fanatical religions and corruption.' FROM games WHERE igdb_id = 1 ON CONFLICT (game_id, language_code) DO NOTHING;
